def _cart_position(event, item, membership=None, subevent=None):
    return CartPosition(event=event, item=item, price=Decimal('23.00'), used_membership=membership, subevent=subevent)


@pytest.mark.django_db
def test_validate_no_membership_needed(event, requiring_ticket):
    event.organizer.membership_types.create(name="Other")
    item = Item.objects.create(event=event, name='Plain ticket', default_price=Decimal('23.00'), admission=True)
    validate_memberships_in_order(None, [_cart_position(event, item)], event)


@pytest.mark.django_db
def test_validate_membership_missing(event, customer, requiring_ticket):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket)], event)
    assert 'membership' in str(excinfo.value)


