@pytest.mark.django_db
def test_validate_membership_valid_from_not_chosen(event, customer, membership_type, requiring_ticket):
    # Membership starts after the event, so only the expiry is checked when the validity start is not chosen yet
    m = customer.memberships.create(
        membership_type=membership_type,
        date_start=now() + timedelta(days=1),
        date_end=now() + timedelta(days=30),
    )
    cp = _cart_position(event, requiring_ticket, m)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [cp], event)
    validate_memberships_in_order(customer, [cp], event, valid_from_not_chosen=True)


@pytest.mark.django_db
def test_validate_membership_testmode_mismatch(event, customer, membership, requiring_ticket):
