@pytest.mark.django_db
def test_validate_membership_max_usages_and_parallel_with_existing_order(event, customer, membership, membership_type,
                                                                          requiring_ticket):
    membership_type.max_usages = 1
    membership_type.save()
    q = event.quotas.create(size=None, name="foo")
    q.items.add(requiring_ticket)
    cp1 = CartPosition.objects.create(
        item=requiring_ticket, price=23, expires=now() + timedelta(days=1), event=event, cart_id="123",
        used_membership=membership
    )
    order = _create_order(event, email='dummy@example.org', positions=[cp1],
                          now_dt=now(),
                          sales_channel=event.organizer.sales_channels.get(identifier="web"),
                          payment_requests=[{
                              "id": "test0",
                              "provider": "banktransfer",
                              "max_value": None,
                              "min_value": None,
                              "multi_use_supported": False,
                              "info_data": {},
                              "pprov": BankTransfer(event),
                              "payment_amount": Decimal("23.00"),
                          }],
                          locale='de', customer=customer)[0]

    cp2 = _cart_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [cp2], event)
    # The order's own usage does not count when that order is being changed
    validate_memberships_in_order(customer, [cp2], event, ignored_order=order)


@pytest.mark.django_db
def test_validate_membership_parallel_usage(event, customer, membership, requiring_ticket, subevent):
    cp_same = [_cart_position(event, requiring_ticket, membership, subevent=subevent) for _ in range(2)]
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, cp_same, event)

    # Different start times are not parallel usage
    validate_memberships_in_order(customer, [
        _cart_position(event, requiring_ticket, membership),
        _cart_position(event, requiring_ticket, membership, subevent=subevent),
    ], event)


@pytest.mark.django_db
def test_validate_membership_parallel_usage_allowed(event, customer, membership, membership_type, requiring_ticket):
    membership_type.allow_parallel_usage = True
    membership_type.save()
    validate_memberships_in_order(customer, [
        _cart_position(event, requiring_ticket, membership),
        _cart_position(event, requiring_ticket, membership),
    ], event)
